INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die ANSI/SPARC-Architektur nur für relationale Datenbanken gedacht?', 2, '[{"text": "Nein", "correct": true, "because": "Allgemeines Modell"}, {"text": "Ja", "correct": false, "because": "Nicht spezifisch relational"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der ANSI/SPARC-Architektur?', 3, '[{"text": "Datenunabhängigkeit", "correct": true, "because": "Trennt Ebenen"}, {"text": "Datenkompression", "correct": false, "because": "Nicht primär"}, {"text": "Schnellere Abfragen", "correct": false, "because": "Indirekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ebenen gehören zur ANSI/SPARC-Architektur?', 5, '[{"text": "Externe Ebene", "correct": true, "because": "Benutzersicht"}, {"text": "Konzeptionelle Ebene", "correct": true, "because": "Logische Struktur"}, {"text": "Physische Ebene", "correct": true, "because": "Speicherung"}, {"text": "Design-Ebene", "correct": false, "because": "Kein Teil"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die konzeptionelle Ebene ist datenbankweit einheitlich. b) Die externe Ebene ist für alle Nutzer gleich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Externe Ebene variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der ANSI/SPARC-Architektur?', 4, '[{"text": "Datenunabhängigkeit", "correct": false, "because": "Kernprinzip"}, {"text": "Ebenentrennung", "correct": false, "because": "Strukturgrundlage"}, {"text": "Farbschema", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die physische Ebene die Speicherung definiert?', 2, '[{"text": "Ja", "correct": true, "because": "Physische Datenorganisation"}, {"text": "Nein", "correct": false, "because": "Kernaufgabe der Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ebene ist für die Benutzersicht zuständig?', 3, '[{"text": "Externe Ebene", "correct": true, "because": "Individuelle Sicht"}, {"text": "Konzeptionelle Ebene", "correct": false, "because": "Gesamtlogik"}, {"text": "Physische Ebene", "correct": false, "because": "Speicherung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur konzeptionellen Ebene?', 5, '[{"text": "Logisches Schema", "correct": true, "because": "Datenbankstruktur"}, {"text": "Beziehungen", "correct": true, "because": "Definiert Verknüpfungen"}, {"text": "Dateiformate", "correct": false, "because": "Physische Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) ANSI/SPARC trennt logische und physische Daten. b) Es ist ein Hardwaremodell. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kein Hardwarefokus"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der ANSI/SPARC-Architektur unwichtig?', 4, '[{"text": "Ebenenunabhängigkeit", "correct": false, "because": "Kernprinzip"}, {"text": "Datenmodellierung", "correct": false, "because": "Grundlage"}, {"text": "Programmiersprache", "correct": true, "because": "Abstrakte Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die externe Ebene für alle Nutzer gleich?', 2, '[{"text": "Nein", "correct": true, "because": "Individuelle Sichten"}, {"text": "Ja", "correct": false, "because": "Nutzerabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die ANSI/SPARC-Architektur?', 4, '[{"text": "Logische Unabhängigkeit", "correct": true, "because": "Änderungen ohne Nutzereffekt"}, {"text": "Physische Unabhängigkeit", "correct": true, "because": "Speicheränderungen isoliert"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ANSI/SPARC veraltet ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Grundprinzipien aktuell"}, {"text": "Ja", "correct": false, "because": "Nicht überholt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich in der ANSI/SPARC-Architektur?', 3, '[{"text": "Datenunabhängigkeit", "correct": true, "because": "Hauptziel"}, {"text": "Schnelligkeit", "correct": false, "because": "Sekundär"}, {"text": "Design", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die physische Ebene beeinflusst die externe nicht direkt. b) Die konzeptionelle Ebene ist nutzerspezifisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Konzeptionell einheitlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat die ANSI/SPARC-Architektur?', 5, '[{"text": "Komplexität", "correct": true, "because": "Ebenenmanagement aufwendig"}, {"text": "Abstraktionsebene", "correct": true, "because": "Kann Implementierung erschweren"}, {"text": "Schnellere Abfragen", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist auf der physischen Ebene unwichtig?', 3, '[{"text": "Speicherstruktur", "correct": false, "because": "Kernaufgabe"}, {"text": "Zugriffsmethoden", "correct": false, "because": "Definiert Effizienz"}, {"text": "Benutzersicht", "correct": true, "because": "Externe Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Trennt ANSI/SPARC Daten und Anwendungen?', 3, '[{"text": "Ja", "correct": true, "because": "Unabhängigkeit fördern"}, {"text": "Nein", "correct": false, "because": "Kernprinzip"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die externe Ebene mehrere Sichten erlaubt?', 2, '[{"text": "Ja", "correct": true, "because": "Nutzerindividuell"}, {"text": "Nein", "correct": false, "because": "Flexibel gestaltet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ebene wähle ich für die logische Datenbankstruktur?', 4, '[{"text": "Konzeptionelle Ebene", "correct": true, "because": "Gesamtdatenmodell"}, {"text": "Externe Ebene", "correct": false, "because": "Benutzersicht"}, {"text": "Physische Ebene", "correct": false, "because": "Speicherung"}]');
